const s = $getWorkflowStaticData('global');
const rows = $input.all().map((i) => i.json);
const cur = rows.find((r) => r.kind === 'cursor');
if (!cur) return [];
const first = s.lastMsg === undefined;
s.lastMsg = Number(cur.max_msg);
s.lastUser = Number(cur.max_user);
// First run only records where we are, so old rows are not replayed.
if (first) return [];
const when = (d) => new Date(d).toLocaleString('en-IN', { timeZone: 'Asia/Kolkata', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' });
const out = [];
for (const m of rows.filter((r) => r.kind === 'message').slice(0, 10)) {
  out.push({ json: { text: 'New contact message\nFrom: ' + m.name + ' <' + m.email + '>\n' + when(m.created_at) + ' IST\n\n' + m.body + '\n\nReply from admin.paisareality.com/messages' } });
}
const signups = rows.filter((r) => r.kind === 'signup');
if (signups.length) {
  out.push({ json: { text: signups.length + ' new sign-up' + (signups.length > 1 ? 's' : '') + ':\n' + signups.slice(0, 20).map((u) => '- ' + (u.name || 'no name') + ' <' + u.email + '>, ' + when(u.created_at)).join('\n') } });
}
return out;
